  }

  function niceStep(span, target) {
    if (!(span > 0)) return 1;
    var raw = span / Math.max(2, target);
    var mag = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10));
    var norm = raw / mag;
    return (norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 5 ? 5 : 10) * mag;
  }

  function tickFmt(step) {
    if (step >= 1) return 0;
    if (step >= 0.1) return 1;
    if (step >= 0.01) return 2;
    return 3;
  }

  function equation(a, b, c) {
    var out = 'y = ';
    if (Math.abs(a) < 1e-6) {
      if (Math.abs(b) < 1e-6) return out + fmt(c);
      out += (b === 1 ? '' : b === -1 ? '−' : fmt(b)) + 'x';
      if (c !== 0) out += (c > 0 ? ' + ' : ' − ') + fmt(Math.abs(c));
      return out;
    }
    out += (a === 1 ? '' : a === -1 ? '−' : fmt(a)) + 'x²';
    if (b !== 0) out += (b > 0 ? ' + ' : ' − ') + (Math.abs(b) === 1 ? '' : fmt(Math.abs(b))) + 'x';
    if (c !== 0) out += (c > 0 ? ' + ' : ' − ') + fmt(Math.abs(c));
    return out;
  }

  function targetWindow(a, b, c) {
    if (Math.abs(a) < 1e-6) {
      var halfLine = 4;
      var ya = -halfLine * b + c, yb = halfLine * b + c;
      var lo = Math.min(ya, yb), hi = Math.max(ya, yb);
      var padY = Math.max(0.8, (hi - lo) * 0.12);
      return { xmin: -halfLine, xmax: halfLine, ymin: lo - padY, ymax: hi + padY };
    }
    var aa = Math.abs(a);
    var h = -b / (2 * a);
    var k = c - (b * b) / (4 * a);
    var up = a > 0;
    var half;
    if (Math.abs(k) < 1e-9) {
      half = Math.max(2.5, Math.sqrt(Math.max(1, Math.abs(c)) / aa) * 1.8);
    } else {
      half = Math.max(2.5, Math.sqrt((2.2 * Math.abs(k)) / aa) / 0.85);
    }
    var reach = aa * half * half;
    var pad = 0.06 * half;
    if (up) {
      return { xmin: h - half - pad, xmax: h + half + pad, ymin: k - reach * 0.22, ymax: k + reach * 0.78 };
    }
    return { xmin: h - half - pad, xmax: h + half + pad, ymin: k - reach * 0.78, ymax: k + reach * 0.22 };
  }

  function holds(win, a, b, c) {
    var h = -b / (2 * a), k = c - (b * b) / (4 * a);
    var spanX = win.xmax - win.xmin, spanY = win.ymax - win.ymin;
    if (!(spanX > 0) || !(spanY > 0)) return false;
    var xPad = spanX * 0.08, yPad = spanY * 0.08;
    if (h < win.xmin + xPad || h > win.xmax - xPad) return false;
    if (k < win.ymin + yPad || k > win.ymax - yPad) return false;
    var yEdge = a > 0 ? win.ymax - yPad : win.ymin + yPad;
    var xEdge = Math.sqrt(Math.abs((yEdge - k) / a));
    if (!(h - xEdge >= win.xmin + xPad && h + xEdge <= win.xmax - xPad)) return false;
    var ideal = targetWindow(a, b, c);
    var rx = spanX / (ideal.xmax - ideal.xmin);
    var ry = spanY / (ideal.ymax - ideal.ymin);
    if (rx > 1.4 || rx < 0.75 || ry > 1.4 || ry < 0.75) return false;
    var vf = (k - win.ymin) / spanY;
    if (a > 0 ? (vf < 0.10 || vf > 0.40) : (vf < 0.60 || vf > 0.90)) return false;
    return true;
  }

  function chooseWindow(a, b, c, prev) {
    if (Math.abs(a) > 1e-6 && prev && holds(prev, a, b, c)) return prev;
    return targetWindow(a, b, c);
  }

  function updateFacts(a, b, c) {
    if (Math.abs(a) < 1e-6) {
      facts.vertex.textContent = '—';
      facts.axis.textContent = '—';
      facts.disc.textContent = 'Δ 不适用';
      facts.roots.textContent = Math.abs(b) < 1e-6 ? '常数函数：水平直线' : '一次函数：斜率 ' + fmt(b);
      return;
    }
    var h = -b / (2 * a);
    var k = c - (b * b) / (4 * a);
    var disc = b * b - 4 * a * c;
    facts.vertex.textContent = '(' + fmt(h) + ', ' + fmt(k) + ')';
    facts.axis.textContent = 'x = ' + fmt(h);
    facts.disc.textContent = 'Δ = ' + fmt(disc);
    if (disc > 1e-9) {
      var sq = Math.sqrt(disc);
      var r1 = (-b - sq) / (2 * a), r2 = (-b + sq) / (2 * a);
      facts.roots.textContent = 'x₁ = ' + fmt(Math.min(r1, r2)) + '，x₂ = ' + fmt(Math.max(r1, r2));
    } else if (disc > -1e-9) {
      facts.roots.textContent = '重根 x = ' + fmt(h);
    } else {
      facts.roots.textContent = '无实根';
    }
  }

  function draw(p, animate) {
    var a = p.a, b = p.b, c = p.c;
    var pw = Math.max(1, Math.round(plot.clientWidth || 0));
    var ph = Math.max(1, Math.round(plot.clientHeight || 0));
    lastW = pw; lastH = ph;
    svg.setAttribute('width', String(pw));
    svg.setAttribute('height', String(ph));
    svg.setAttribute('viewBox', '0 0 ' + pw + ' ' + ph);
    while (svg.firstChild) svg.removeChild(svg.firstChild);

    var win = chooseWindow(a, b, c, last ? last.win : null);
    var padL = 46, padR = 20, padT = 16, padB = 28;
    var iw = Math.max(40, pw - padL - padR);
    var ih = Math.max(40, ph - padT - padB);
    var spanX = win.xmax - win.xmin;
    var spanY = win.ymax - win.ymin;
    if (!(spanX > 0)) spanX = 1;
    if (!(spanY > 0)) spanY = 1;

    function sx(x) { return padL + ((x - win.xmin) / spanX) * iw; }
    function sy(y) { return padT + ((win.ymax - y) / spanY) * ih; }

    var clipId = 'quad-viz-clip';
    var defs = el('defs');
    var clip = el('clipPath', { id: clipId });
    clip.appendChild(el('rect', { x: padL, y: padT, width: iw, height: ih }));
    defs.appendChild(clip);
    svg.appendChild(defs);

    var xStep = niceStep(spanX, 9);
    var yStep = niceStep(spanY, 6);
    var xDec = tickFmt(xStep), yDec = tickFmt(yStep);

    var xTicks = [], yTicks = [];
    var gx = 0, gy = 0, v;
    for (v = Math.ceil(win.xmin / xStep - 1e-9) * xStep; v <= win.xmax + xStep * 1e-6 && gx < 60; v += xStep, gx++) {
      xTicks.push(round(v, 6));
    }
    for (v = Math.ceil(win.ymin / yStep - 1e-9) * yStep; v <= win.ymax + yStep * 1e-6 && gy < 40; v += yStep, gy++) {
      yTicks.push(round(v, 6));
    }

    var grid = el('g');
    xTicks.forEach(function (tx) {
      grid.appendChild(el('line', { x1: sx(tx), y1: padT, x2: sx(tx), y2: padT + ih, class: 'grid-line' }));
    });
    yTicks.forEach(function (ty) {
      grid.appendChild(el('line', { x1: padL, y1: sy(ty), x2: padL + iw, y2: sy(ty), class: 'grid-line' }));
    });
    svg.appendChild(grid);

    var xVisible = win.ymin <= 0 && 0 <= win.ymax;
    var yVisible = win.xmin <= 0 && 0 <= win.xmax;
    var xAxisY = sy(0);
    var yAxisX = sx(0);
    var axis = el('g');

    if (xVisible) {
      axis.appendChild(el('line', { x1: padL, y1: xAxisY, x2: padL + iw, y2: xAxisY, class: 'axis-line' }));
      axis.appendChild(el('path', { d: 'M' + (padL + iw) + ',' + xAxisY + ' l-8,-4 v8 z', fill: 'var(--viz-axis)' }));
      axis.appendChild(el('text', { class: 'axis-label axis-label-x', x: padL + iw, y: xAxisY - 10, 'text-anchor': 'end' }, 'x'));
    }
    if (yVisible) {
      axis.appendChild(el('line', { x1: yAxisX, y1: padT, x2: yAxisX, y2: padT + ih, class: 'axis-line' }));
      axis.appendChild(el('path', { d: 'M' + yAxisX + ',' + (padT - 1) + ' l-4,8 h8 z', fill: 'var(--viz-axis)' }));
      axis.appendChild(el('text', { class: 'axis-label axis-label-y', x: yAxisX + 10, y: padT + 14 }, 'y'));
    }

    var xLabelBase = xVisible ? xAxisY + 15 : padT + ih + 15;
    var lastRight = -Infinity;
    xTicks.forEach(function (tx) {
      var isZero = Math.abs(tx) < xStep * 1e-6;
      if (isZero && xVisible && yVisible) return;
      var label = fmt(tx, xDec);
      var px = sx(tx);
      var halfW = label.length * 3.1 + 4;
      if (px - halfW < padL - 4) return;
      if (px - halfW < lastRight + 8) return;
      lastRight = px + halfW;
      axis.appendChild(el('text', { x: px, y: xLabelBase, 'text-anchor': 'middle', class: 'tick-text' }, label));
    });

    var skip = 1;
    while (yTicks.length / skip > 8) skip += 1;
    yTicks.forEach(function (ty, i) {
      if (i % skip !== 0) return;
      if (Math.abs(ty) < yStep * 1e-6 && xVisible && yVisible) return;
      axis.appendChild(el('text', { x: padL - 8, y: sy(ty) + 3.5, 'text-anchor': 'end', class: 'tick-text' }, fmt(ty, yDec)));
    });

    if (xVisible && yVisible) {
      axis.appendChild(el('text', { x: yAxisX - 6, y: xAxisY + 14, 'text-anchor': 'end', class: 'tick-text' }, '0'));
    }
    svg.appendChild(axis);

    var hx = 0, ky = 0;
    var quadratic = Math.abs(a) > 1e-6;
    if (quadratic) {
      hx = -b / (2 * a);
      ky = c - (b * b) / (4 * a);
      if (hx >= win.xmin && hx <= win.xmax) {
        svg.appendChild(el('line', {
          x1: sx(hx), y1: padT, x2: sx(hx), y2: padT + ih,
          class: 'sym-line', 'clip-path': 'url(#' + clipId + ')'
        }));
      }
    }

    var d = '';
    var n = Math.min(720, Math.max(180, Math.round(iw * 2)));
    for (var i = 0; i <= n; i += 1) {
      var xx = win.xmin + spanX * (i / n);
      var yy = a * xx * xx + b * xx + c;
      d += (i === 0 ? 'M' : 'L') + sx(xx).toFixed(2) + ',' + sy(yy).toFixed(2);
    }
    var curve = el('path', { d: d, class: 'curve', 'clip-path': 'url(#' + clipId + ')' });
    svg.appendChild(curve);

    if (animate && !reduced) {
      try {
        var len = curve.getTotalLength();
        curve.style.strokeDasharray = String(len);
        curve.style.strokeDashoffset = String(len);
        curve.getBoundingClientRect();
        curve.style.transition = 'stroke-dashoffset 600ms ease-out';
        curve.style.strokeDashoffset = '0';
        curve.addEventListener('transitionend', function () {
          curve.style.strokeDasharray = '';
          curve.style.strokeDashoffset = '';
        }, { once: true });
      } catch (err) { /* keep the plain curve */ }
    }

    var marks = el('g');
    if (quadratic) {
      if (ky >= win.ymin && ky <= win.ymax && hx >= win.xmin && hx <= win.xmax) {
        marks.appendChild(el('circle', { cx: sx(hx), cy: sy(ky), r: 4.5, class: 'vertex-dot' }));
        var label = '顶点 (' + fmt(hx) + ', ' + fmt(ky) + ')';
        var lx = sx(hx) + 10;
        var ly = a > 0 ? sy(ky) - 9 : sy(ky) + 17;
        var anchor = 'start';
        if (lx + 96 > padL + iw) { lx = sx(hx) - 10; anchor = 'end'; }
        if (ly < padT + 12) ly = padT + 12;
        if (ly > padT + ih - 4) ly = padT + ih - 4;
        marks.appendChild(el('text', { x: lx, y: ly, 'text-anchor': anchor, class: 'vertex-label' }, label));
      }
      var disc = b * b - 4 * a * c;
      if (disc >= 0 && xVisible) {
        var sq = Math.sqrt(disc);
        [(-b - sq) / (2 * a), (-b + sq) / (2 * a)].forEach(function (rx) {
          if (rx < win.xmin || rx > win.xmax) return;
          marks.appendChild(el('circle', { cx: sx(rx), cy: xAxisY, r: 4, class: 'root-dot' }));
        });
      }
    }
    svg.appendChild(marks);

    last = { a: a, b: b, c: c, win: win };
  }

  function render(raw) {
    var a = round(Number(raw.a) || 0, 1);
    var b = round(Number(raw.b) || 0, 1);
    var c = round(Number(raw.c) || 0, 1);
    var eq = equation(a, b, c);
    updateFacts(a, b, c);
    draw({ a: a, b: b, c: c }, !entered);
    entered = true;
    return { equation: eq, a: dec1(a), b: dec1(b), c: dec1(c) };
  }

  dshViz.bind('#quad-viz', render);

  if (typeof ResizeObserver === 'function') {
    var ro = new ResizeObserver(function () {
      if (!last) return;
      var w = Math.round(plot.clientWidth || 0);
      var h = Math.round(plot.clientHeight || 0);
      if (!w || !h || (w === lastW && h === lastH)) return;
      draw({ a: last.a, b: last.b, c: last.c }, false);
    });
    ro.observe(plot);
  }
})();
</script>"}
